def parse_grid(text, label):
 sec=text.split(label+' (')[1].split('):',1)[1]
 # until next blank, rows start lines
 rows=[]
 for line in sec.strip().splitlines():
  if not re.match(r'^[0-9 ]+$',line.strip()): break
  vals=list(map(int,line.split()));
  if vals: rows.append(vals)
 return rows
