from collections import deque

def comps(g):
 R,C=len(g),len(g[0]); labels=[[-1]*C for _ in range(R)]; cc=[]
 for r in range(R):
  for c in range(C):
   if g[r][c] and labels[r][c]<0:
    k=len(cc); q=[(r,c)]; labels[r][c]=k; cells=[]
    while q:
     x,y=q.pop(); cells.append((x,y))
     for xx,yy in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
      if 0<=xx<R and 0<=yy<C and g[xx][yy] and labels[xx][yy]<0: labels[xx][yy]=k;q.append((xx,yy))
    cc.append(cells)
 return labels,cc

